 let bar=false; for(let i=0;i<300;i++){ if(document.querySelector('.aq-map-saving')) bar=true; if(count()>c0) break; await w(10)} res.add_story={ms:Math.round(performance.now()-t0),savingBar:bar};
 res.longtasks=window.__lt; return res }

